alter table private.evidence_objects add column appeal_at timestamptz,add column claim_token uuid,add column claimed_at timestamptz;create index evidence_retention_due_idx on private.evidence_objects(retention_until,id)where deleted_at is null and legal_hold_at is null and appeal_at is null;
create or replace function public.claim_expired_evidence(p_batch_size int,p_claim_token uuid)returns table(evidence_id uuid,object_path text)language plpgsql security definer set search_path=pg_catalog,private as $$begin if current_setting('request.jwt.claim.role',true)<>'service_role'then raise exception using errcode='P0001',detail='PERMISSION_DENIED';end if;return query with claimed as(select id from private.evidence_objects where retention_until<=now()and deleted_at is null and legal_hold_at is null and appeal_at is null and(claimed_at is null or claimed_at<now()-interval'15 minutes')order by retention_until,id for update skip locked limit greatest(1,least(p_batch_size,100)))update private.evidence_objects e set claim_token=p_claim_token,claimed_at=now()from claimed where e.id=claimed.id returning e.id,e.object_path;end$$;
create or replace function public.finalize_evidence_deletion(p_evidence_id uuid,p_claim_token uuid)returns boolean language plpgsql security definer set search_path=pg_catalog,private as $$begin if current_setting('request.jwt.claim.role',true)<>'service_role'then raise exception using errcode='P0001',detail='PERMISSION_DENIED';end if;update private.evidence_objects set deleted_at=now(),object_path='deleted/'||id::text,claim_token=null,claimed_at=null where id=p_evidence_id and claim_token=p_claim_token and legal_hold_at is null and appeal_at is null;if not found then return false;end if;insert into private.audit_log(action,aggregate_type,aggregate_id,after_state)values('evidence.deleted','evidence',p_evidence_id,'{"sensitivePathRemoved":true}');return true;end$$;revoke all on function public.claim_expired_evidence(int,uuid),public.finalize_evidence_deletion(uuid,uuid)from public,anon,authenticated;grant execute on function public.claim_expired_evidence(int,uuid),public.finalize_evidence_deletion(uuid,uuid)to service_role;
